{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"OrdinalAutoMLResult","description":"Complete ordinal AutoML results.","type":"object","properties":{"leaderboard":{"description":"Every configuration that finished, best first.","type":"array","items":{"$ref":"#/$defs/OrdinalAutoMLEntry"}},"skipped":{"description":"Configurations excluded because a fold could not be fitted, with the reason.","type":"array","items":{"$ref":"#/$defs/OrdinalAutoMLSkip"}},"best_index":{"description":"Index of the winning entry inside `leaderboard`.","type":"integer","format":"uint","minimum":0},"total_models_tried":{"description":"Number of configurations on the leaderboard. Excluded ones are counted in `skipped`.","type":"integer","format":"uint","minimum":0},"total_time_secs":{"description":"Wall clock seconds for the whole sweep, including data loading and the final refit.","type":"number","format":"double"},"metric":{"description":"Metric the leaderboard was ranked by.","type":"string"},"higher_is_better":{"description":"False for the two error metrics, where the SMALLEST `cv_score` is the winner.","type":"boolean"},"n_levels":{"description":"Number of ordered levels every candidate was fitted against.","type":"integer","format":"uint","minimum":0},"n_folds":{"description":"Number of cross-validation folds.","type":"integer","format":"uint","minimum":0},"n_samples":{"description":"Rows the sweep ran on.","type":"integer","format":"uint","minimum":0}},"required":["leaderboard","skipped","best_index","total_models_tried","total_time_secs","metric","higher_is_better","n_levels","n_folds","n_samples"],"$defs":{"OrdinalAutoMLEntry":{"description":"One configuration that survived cross-validation, as it appears on the leaderboard.","type":"object","properties":{"model_type":{"description":"Stable model kind, the same identifier the rest of the catalog uses for this model:
